<script setup>import {state,actions,displayTime} from '../../domain/prototypeStore.js'</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">接</div><div><h2>系统对接</h2><p>查看外部能力接入状态</p></div></div><div class="card-grid"><article v-for="a in state.adapters" :key="a.key" class="panel"><h3>{{a.name}}</h3><p>{{a.note}}</p><p>状态：<strong>{{a.status}}</strong></p><small>最近更新：{{displayTime(a.updatedAt)}}</small><div class="button-row"><button class="secondary-button" @click="actions.retryAdapter(a.key)">重新检查</button></div></article></div></section></template>
